describe('Past-Date Field Validation - Future Date Submission', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should display error when submitting form with future date in past-date field', () => {
    // Intercept the form submission API
    cy.intercept('POST', '/api/form-submit').as('formSubmit');

    // Get the form input element
    cy.get('[data-testid="past-date-input"]').type('2025-01-01');

    // Verify error message is visible
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Date must be in the past');

    // Verify error class is applied
    cy.get('[data-testid="error-message"]').should('have.class', 'error');

    // Verify form is not submitted
    cy.get('[data-testid="submit-button"]').should('be.disabled');

    // Verify API call is not made
    cy.wait('@formSubmit').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
    });
  });

  it('should clear error when correct date is entered', () => {
    // Intercept the form submission API
    cy.intercept('POST', '/api/form-submit').as('formSubmit');

    // Get the form input element
    cy.get('[data-testid="past-date-input"]').type('2023-01-01');

    // Verify error message is gone
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify form is enabled
    cy.get('[data-testid="submit-button"]').should('not.be.disabled');

    // Verify API call is made
    cy.wait('@formSubmit').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });
  });
});
